 if key=='teaching':
  body += '<section class="section wrap"><p class="eyebrow">Resurse și mobilitate</p><h2>Materiale didactice și colaborare internațională</h2><div class="prose"><h3>Probleme avansate de măsurare și estimare în instrumentație</h3><p>Curs și laborator în format electronic, 100 de pagini, consemnate în fișa CNATDCU.</p><h3>Cursuri și îndrumare</h3><p>Suporturi de curs pentru măsurări electrice și electronice, achiziția și prelucrarea datelor în procese industriale și senzori biomedicali. Catalogul publicațiilor include acum și îndrumare de laborator pentru inginerie electrică, energetică și instrumentație biomedicală.</p><a href="publications.html">Consultați catalogul publicațiilor →</a><h3>Mobilități Erasmus+ România–Grecia</h3><p>Coordonarea programului de mobilități pentru studenți și personal universitar în cadrul acordului interinstituțional Erasmus+ 2014–2021.</p></div></section>'
 if key=='research':
  body += '<section class="section wrap"><p class="eyebrow">Transfer către industrie</p><h2>Colaborări industriale</h2><div class="course-list"><article class="course"><small>2006 · Membru în echipă</small><h3>ALRO Slatina</h3><p>Evaluarea conținutului de armonici și instalație de creștere a factorului de putere. Contract nr. 7153/2006, UPB–CMIM / ALRO Slatina.</p></article><article class="course"><small>2006 · Membru în echipă</small><h3>Transelectrica SA</h3><p>Analiza calității energiei electrice în sistemul de transport și studiul posibilităților practice de reducere a erorilor de măsurare în contorizarea energiei electrice.</p></article></div></section>'
